const SOURCES={h1:{name:'贵州茅台 2026 年半年度报告',date:'2026-08-15',url:'https://static.cninfo.com.cn/finalpage/2026-08-15/1225475868.PDF'},fy:{name:'贵州茅台 2025 年年度报告',date:'2026-04-17',url:'https://big5.sse.com.cn/site/cht/www.sse.com.cn/disclosure/listedinfo/announcement/c/new/2026-04-17/600519_20260417_9QS4.pdf'}};
const DATA={
 h1:{label:'2026 年 1—6 月',base:'2025 年 1—6 月',source:SOURCES.h1,raw:{revenue:[90703260964.48,89389354416.84],profit:[44516880421.86,45402962298.10],cash:[70690750119.06,13119061031.33],cost:[9473762565.88,7777491083.93],salesCash:[98421697395.39,95086614960.23]},pages:{headline:5,drivers:8,cash:34,cost:8},note:'公司在半年报中解释，经营现金流净额变化主要涉及集团财务公司吸收成员单位存款增加，以及不可随时支取的同业存款减少。'},
 fy:{label:'2025 年度',base:'2024 年度',source:SOURCES.fy,raw:{revenue:[168838102514.79,170899152276.34],profit:[82320067101.68,86228146421.62],cash:[61522204989.35,92463692168.43]},pages:{headline:7,drivers:7,cash:7},note:'年报说明，经营现金流净额下降主要涉及集团财务公司吸收成员单位存款减少，以及不可随时支取的同业存款增加。'}
};
let period='h1',cards=[];
const round=(n,d=1)=>Number(n).toFixed(d),yi=n=>round(n/1e8,1)+' 亿元',change=(a,b)=>(a/b-1)*100,sign=n=>(n>0?'+':'')+round(n,2)+'%',pdf=(source,page)=>source.url+'#page='+page;
function metric(label,pair,descriptor){let delta=change(...pair);return `<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${yi(pair[0])}</div><div class="metric-foot">同比 <strong class="${delta>=0?'up':'down'}">${sign(delta)}</strong> · ${descriptor}</div></div>`}
function renderMetrics(){const d=DATA[period],r=d.raw;document.querySelector('#metrics').innerHTML=metric('营业收入',r.revenue,d.label)+metric('归母净利润',r.profit,d.label)+metric('经营活动现金流净额',r.cash,d.label)+(period==='h1'?`<div class="metric"><div class="metric-label">营业毛利率 · 计算值</div><div class="metric-value">${round((1-r.cost[0]/r.revenue[0])*100,2)}%</div><div class="metric-foot">上年同期 ${round((1-r.cost[1]/r.revenue[1])*100,2)}% · 合并口径</div></div>`:`<div class="metric"><div class="metric-label">财报期次</div><div class="metric-value">2025 FY</div><div class="metric-foot">对比 2024 FY · 人民币合并口径</div></div>`)}
function makeCards(){const d=DATA[period],r=d.raw,s=d.source,p=d.pages,rev=change(...r.revenue),pro=change(...r.profit),cash=change(...r.cash);let arr=[
 {type:'fact',label:'客观事实',title:`收入同比 ${sign(rev)}，归母净利同比 ${sign(pro)}`,summary:`${d.label}合并口径。两项指标方向${Math.sign(rev)===Math.sign(pro)?'一致':'相反'}。`,source:s,page:p.headline,raw:[['营业收入 · 本期',yi(r.revenue[0])],['营业收入 · 对比期',yi(r.revenue[1])],['归母净利润 · 本期',yi(r.profit[0])],['归母净利润 · 对比期',yi(r.profit[1])]],formula:'同比 = 本期 ÷ 对比期 − 1。财报原值单位为元，页面换算为亿元。',meaning:'这是财报披露值及确定性同比计算；仅凭这两项无法解释全部原因。'},
 {type:'mixed',label:'矛盾信号',title:`经营现金流同比 ${sign(cash)}，不能直接等同主营改善`,summary:d.note,source:s,page:p.drivers,raw:[['经营现金流净额 · 本期',yi(r.cash[0])],['经营现金流净额 · 对比期',yi(r.cash[1])],['同比变化',sign(cash)]],formula:'同比 = 本期 ÷ 对比期 − 1。现金流为合并口径，包含集团财务公司相关活动。',meaning:'现金流变动是事实；把全部变化归因于白酒销售回款属于过度推断。管理层说明提供了需要进一步拆解的线索。'},
 {type:'infer',label:'分析推断',title:period==='h1'?'成本增速高于收入，毛利率承压':'收入与利润同时回落，需继续拆解结构',summary:period==='h1'?'营业成本同比 +21.81%，高于收入 +1.47%；按合并收入和成本计算，毛利率较同期下降。':'仅凭年度汇总数据，尚不能确定销量、产品结构与费用各自的贡献。',source:s,page:period==='h1'?p.cost:p.headline,raw:period==='h1'?[['营业成本 · 本期',yi(r.cost[0])],['营业成本 · 对比期',yi(r.cost[1])],['毛利率 · 本期',round((1-r.cost[0]/r.revenue[0])*100,2)+'%'],['毛利率 · 同期',round((1-r.cost[1]/r.revenue[1])*100,2)+'%']]:[['营业收入同比',sign(rev)],['归母净利同比',sign(pro)]],formula:period==='h1'?'毛利率 = (营业收入 − 营业成本) ÷ 营业收入；按合并财报字段计算。':'同比 = 本期 ÷ 上年同期 − 1。',meaning:period==='h1'?'成本与收入增速差是事实；“毛利率承压”为基于公式的分析推断。':'需要结合品类、渠道和费用明细，才能确认驱动因素。'},
 {type:'unknown',label:'待验证',title:'估值是否合理：缺少同日价格与可比口径',summary:'当前无可信的同日股价、估值分位及同行样本，暂不作估值高低判断。',raw:[['缺失字段','同日股价、市值、同行估值'],['下一步','接入行情与一致口径同行数据']],meaning:'把估值标记为待验证，避免用过期价格或孤立倍数生成结论。'},
 {type:'unknown',label:'待验证',title:'行情与行业位置：尚无可比数据',summary:'未接入复权行情、行业成分和同业财务序列。当前无法判断相对强弱。',raw:[['缺失字段','复权 K 线、行业成分、同行指标'],['下一步','接入同一时点、同一口径的数据']],meaning:'行情走势与行业排名需要明确窗口、复权方式和样本边界。'},
 {type:'unknown',label:'待验证',title:'重要事件与风险：动态信息未覆盖',summary:'样例只纳入已披露财报。此处不代表报告日之后没有新事件。',raw:[['覆盖范围','2026 半年报、2025 年报'],['下一步','接入公告与新闻，并记录披露时间']],meaning:'用户应继续检查最新公告，特别是半年报之后的事件。'}
];if(period==='h1')arr.splice(3,0,{type:'fact',label:'客观事实',title:'销售商品与劳务收到现金同比小幅增长',summary:'合并现金流量表披露 984.22 亿元，上年同期 950.87 亿元；与经营现金流净额的增幅不同。',source:s,page:p.cash,raw:[['本期',yi(r.salesCash[0])],['上年同期',yi(r.salesCash[1])],['同比',sign(change(...r.salesCash))]],formula:'同比 = 本期 ÷ 上年同期 − 1。',meaning:'这项数据能帮助核查销售回款，但仍不能单独替代主营业务现金流分析。'});return arr}
function renderCards(){cards=makeCards();document.querySelector('#evidenceGrid').innerHTML=cards.map((c,i)=>`<button class="evidence-card" data-card="${i}"><div class="card-top"><span class="tag ${c.type}">${c.label}</span><span class="arrow">↗</span></div><h3>${c.title}</h3><p>${c.summary}</p><div class="card-source">${c.source?`${c.source.name} · ${c.source.date}`:'数据缺失 · 未生成判断'}</div></button>`).join('');document.querySelectorAll('[data-card]').forEach(b=>b.addEventListener('click',()=>openCard(cards[Number(b.dataset.card)])))}
function openCard(c){document.querySelector('#drawerBody').innerHTML=`<div class="eyebrow">EVIDENCE DETAIL</div><h2>${c.title}</h2><span class="tag ${c.type}">${c.label}</span><h3>判断与边界</h3><p>${c.meaning}</p><h3>原始字段</h3><div class="raw">${c.raw.map(x=>`<div class="raw-line"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div>${c.formula?`<h3>计算口径</h3><p>${c.formula}</p>`:''}<h3>来源与时点</h3><p>${c.source?`${c.source.name}；披露日期 ${c.source.date}；PDF 第 ${c.page} 页。`:'当前样例无可核验数据，暂不输出结论。'}</p>${c.source?`<a class="source-link" href="${pdf(c.source,c.page)}" target="_blank" rel="noopener">打开财报原文 · 第 ${c.page} 页 ↗</a>`:''}`;document.querySelector('#backdrop').hidden=false;document.querySelector('#drawer').classList.add('open');document.querySelector('#drawer').setAttribute('aria-hidden','false')}
function closeDrawer(){document.querySelector('#drawer').classList.remove('open');document.querySelector('#drawer').setAttribute('aria-hidden','true');document.querySelector('#backdrop').hidden=true}
function answer(q){let title='',body='',refs='';if(/现金|回款|销售商品/.test(q)){const c=cards.find(x=>x.type==='mixed'),x=period==='h1'?cards.find(x=>x.title.includes('销售商品')):null;title='现金流需要拆开看';body=`${c.title}。${DATA[period].note}${x?' 同期“销售商品、提供劳务收到的现金”仅同比 '+sign(change(...DATA.h1.raw.salesCash))+'，因此需要区分销售回款与财务公司相关项目。':''}`;refs=period==='h1'?'依据：2026 半年报第 5、8、34 页。':'依据：2025 年报主要会计数据与现金流说明。'}else if(/收入|利润|成本|毛利|经营/.test(q)){let c=cards[0],x=cards[2];title='收入与利润的方向需要分别核查';body=`${c.title}。${x.summary} ${x.meaning}`;refs=`依据：${DATA[period].source.name}。`}else if(/估值|市盈|价格|股价|贵|便宜/.test(q)){title='当前无法判断估值高低';body='样例没有同日股价、估值分位和同口径同行比较。请先补齐这些数据，再定义“合理”的比较基准。';refs='状态：待验证。'}else if(/行业|同行|排名|走势|行情/.test(q)){title='当前缺少相对比较依据';body='需要确定同行样本、比较期和复权方式。当前样例没有对应数据，因此不生成行业排名或走势判断。';refs='状态：待验证。'}else{title='这个问题超出当前证据范围';body='当前可核查收入、利润、成本与现金流。请换一个问题，或先接入所需的数据与原文。';refs='系统没有为未覆盖的问题编造结论。'}document.querySelector('#answer').innerHTML=`<div class="answer-head">✦ 证据回答 · ${title}</div><p>${body}</p><small>${refs} 问题识别采用可审计关键词规则；解释已核对原文。</small>`}
document.querySelector('#askBtn').addEventListener('click',()=>answer(document.querySelector('#question').value.trim()));document.querySelector('#question').addEventListener('keydown',e=>{if(e.key==='Enter')answer(e.target.value.trim())});document.querySelectorAll('[data-q]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#question').value=b.dataset.q;answer(b.dataset.q)}));document.querySelectorAll('[data-period]').forEach(b=>b.addEventListener('click',()=>{period=b.dataset.period;document.querySelectorAll('[data-period]').forEach(x=>x.classList.toggle('selected',x===b));renderMetrics();renderCards();answer(document.querySelector('#question').value.trim())}));document.querySelector('#closeDrawer').addEventListener('click',closeDrawer);document.querySelector('#backdrop').addEventListener('click',closeDrawer);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});renderMetrics();renderCards();answer(document.querySelector('#question').value);
